{
  "iteration": 2,
  "pcvs": [
    {
      "name": "sampling_copy_count",
      "expression": "int(not self.all_greedy) + int(not self.no_top_p) + int(not self.no_top_k) + 3 * int(not self.no_penalties)",
      "rationale": "Tracks conditional tensor-copy overhead."
    },
    {
      "name": "penalties_enabled",
      "expression": "int(not self.no_penalties)",
      "rationale": "Captures fixed overhead from constructing prompt token metadata."
    },
    {
      "name": "prompt_rows",
      "expression": "self.num_reqs if not self.no_penalties else 0",
      "rationale": "Tracks the per-request prompt padding loop."
    },
    {
      "name": "empty_batch",
      "expression": "int(self.num_reqs == 0)",
      "rationale": "Separates empty initialization from active greedy batches, which previously shared the state with the largest unexplained share."
    }
  ],
  "hypothesis": "The largest irregularity comes from grouping empty initialization with active greedy batches. Separating that entry state should improve the worst state while retaining the dominant copy and prompt-processing predictors."
}
